{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "name": "astryx",
    "version": "0.7.12",
    "commands": [
      "blog",
      "build",
      "component",
      "discover",
      "docs",
      "doctor",
      "experimental",
      "gap-report",
      "hook",
      "init",
      "integration",
      "manifest",
      "search",
      "swizzle",
      "template",
      "theme",
      "upgrade"
    ],
    "jsonSupported": [
      "blog",
      "build",
      "component",
      "discover",
      "docs",
      "doctor",
      "doctor integration components",
      "doctor integration docs",
      "doctor integration templates",
      "doctor integration validate",
      "experimental icon",
      "experimental icon add",
      "experimental icon map",
      "experimental icon new-definition",
      "experimental icon new-set",
      "experimental icon use",
      "experimental render",
      "gap-report",
      "hook",
      "init",
      "integration add",
      "integration check",
      "integration pack",
      "integration verify",
      "manifest",
      "search",
      "swizzle",
      "template",
      "theme add",
      "theme build",
      "theme eject",
      "theme list",
      "theme palette generate",
      "theme remove",
      "theme targets",
      "theme template",
      "theme use",
      "upgrade"
    ],
    "manifest": {
      "name": "astryx",
      "version": "0.7.12",
      "apiVersion": 1,
      "description": "Design system CLI — components, themes, and tooling",
      "globalOptions": [
        {
          "flag": "-V, --version",
          "description": "output the version number",
          "type": "boolean"
        },
        {
          "flag": "--zh",
          "description": "Simplified Chinese for component reads and for docs topics that have a translation (English otherwise)",
          "type": "boolean"
        },
        {
          "flag": "--dense",
          "description": "Token-efficient dense text for component <Name> and docs <topic> reads",
          "type": "boolean"
        },
        {
          "flag": "--lang <locale>",
          "description": "Language or format for component and docs reads: en (default), zh (as --zh), or dense (as --dense)",
          "type": "enum",
          "choices": [
            "en",
            "zh",
            "dense"
          ]
        },
        {
          "flag": "--detail <level>",
          "description": "Detail level for component, hook, and docs tree reads (e.g. docs cli/commands/build), and for theme build reports. Lists default to brief; theme build prints one line per built theme unless full, which adds the install example and font recipe",
          "type": "enum",
          "choices": [
            "full",
            "compact",
            "brief"
          ],
          "default": "full"
        },
        {
          "flag": "--json",
          "description": "Output as typed JSON. Success envelope: { apiVersion, type, package?, data, meta? }. Error envelope: { apiVersion, error, code, suggestions? }.",
          "type": "boolean"
        }
      ],
      "commands": [
        {
          "name": "blog",
          "description": "Read the Astryx blog from the published feed",
          "arguments": [
            {
              "name": "slug",
              "required": false,
              "variadic": false,
              "description": ""
            }
          ],
          "options": [],
          "json": true,
          "responseTypes": [
            "blog.list",
            "blog.detail"
          ],
          "examples": [
            "astryx blog",
            "astryx blog introducing-astryx --json"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "success"
            },
            {
              "code": 1,
              "when": "unknown slug, or the feed or a post cannot be fetched"
            }
          ],
          "outsideProject": "same"
        },
        {
          "name": "build",
          "description": "Build a page: the template to start from, or the workflow playbook (no query)",
          "arguments": [
            {
              "name": "query",
              "required": false,
              "variadic": false,
              "description": ""
            }
          ],
          "options": [
            {
              "flag": "--type <domain>",
              "description": "Filter the kit to one domain (component|hook|doc|template|theme); doc and theme give an empty kit",
              "type": "string"
            },
            {
              "flag": "--limit <n>",
              "description": "Max candidates to draw from (default 60)",
              "type": "string"
            },
            {
              "flag": "--verbose",
              "description": "Verbose output (every block and component, full descriptions, import paths and match reason)",
              "type": "boolean"
            }
          ],
          "json": true,
          "responseTypes": [
            "build.help",
            "build.kit"
          ],
          "examples": [
            "astryx build",
            "astryx build \"analytics dashboard\" --json"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "success (including zero matches)"
            },
            {
              "code": 1,
              "when": "invalid --type, a --limit that is not a positive integer, or a query when @astryxdesign/core cannot be found (the playbook needs no core)"
            }
          ],
          "outsideProject": "same"
        },
        {
          "name": "component",
          "description": "List components or print component docs",
          "arguments": [
            {
              "name": "names",
              "required": false,
              "variadic": true,
              "description": "One or more exact selectors. Use Name, package/Name, @scope/package/Name, or @scope/package@version/Name. Two or more return one ordered batch. At most 100 selectors are accepted."
            }
          ],
          "options": [
            {
              "flag": "--list",
              "description": "List every component (the same as giving no name)",
              "type": "boolean"
            },
            {
              "flag": "--category <category>",
              "description": "List one component group, e.g. --category Layout or --category Avatar (an unknown group lists the valid ones)",
              "type": "string"
            },
            {
              "flag": "--props",
              "description": "Print only the props table",
              "type": "boolean"
            },
            {
              "flag": "--source",
              "description": "Print component source code",
              "type": "boolean"
            },
            {
              "flag": "--showcase",
              "description": "Print showcase source code",
              "type": "boolean"
            },
            {
              "flag": "--blocks",
              "description": "List example blocks: showcase, examples, and related",
              "type": "boolean"
            },
            {
              "flag": "--package <name>",
              "description": "Scope lookup to an external package (e.g. @acme/xds-widgets). Use @astryxdesign/core to select an original replaced by an integration component.",
              "type": "string"
            }
          ],
          "json": true,
          "responseTypes": [
            "component.list",
            "component.batch",
            "component.detail",
            "component.detail.props",
            "component.detail.source",
            "component.detail.showcase",
            "component.detail.blocks"
          ],
          "examples": [
            "astryx component --list",
            "astryx component Button Badge Text",
            "astryx component Button --props --json",
            "astryx component SideNav --package @astryxdesign/core"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "success"
            },
            {
              "code": 1,
              "when": "unknown component, category, or package; more than 100 selectors; any batch row is unresolved; or @astryxdesign/core cannot be resolved"
            }
          ],
          "outsideProject": "same"
        },
        {
          "name": "discover",
          "description": "Browse and search integrations: the ones you have and the ones you could add",
          "arguments": [
            {
              "name": "query",
              "required": false,
              "variadic": false,
              "description": ""
            }
          ],
          "options": [
            {
              "flag": "--components",
              "description": "In the package list, print every component, and every other item, of each package instead of the first 10 and a \"+N more\" count. No effect on --json output or on a package, component, or search query.",
              "type": "boolean"
            },
            {
              "flag": "--type <kind>",
              "description": "Only one kind: component, template, doc, theme, codemod, or agent-doc. In the list, only packages that add it; in a search, only items of that kind.",
              "type": "string"
            },
            {
              "flag": "--installed",
              "description": "Only what this project has. Cannot be set with --available.",
              "type": "boolean"
            },
            {
              "flag": "--available",
              "description": "Only what this project could add. Cannot be set with --installed.",
              "type": "boolean"
            },
            {
              "flag": "--limit <n>",
              "description": "Max number of search results, a positive integer (default 20).",
              "type": "string"
            }
          ],
          "json": true,
          "responseTypes": [
            "discover.list",
            "discover.detail",
            "discover.detail.doc",
            "discover.item",
            "discover.search"
          ],
          "examples": [
            "astryx discover",
            "astryx discover --components",
            "astryx discover --type theme",
            "astryx discover @acme/ui",
            "astryx discover @acme/ui@2.1.0",
            "astryx discover dashboard --type template --available"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "success"
            },
            {
              "code": 1,
              "when": "unknown package, version, component, or item; a malformed doc; an invalid --type or --limit; --installed with --available; or a blank query when packages are discovered"
            }
          ],
          "outsideProject": "same"
        },
        {
          "name": "docs",
          "description": "Print reference docs",
          "arguments": [
            {
              "name": "topic",
              "required": false,
              "variadic": false,
              "description": ""
            },
            {
              "name": "section",
              "required": false,
              "variadic": false,
              "description": ""
            }
          ],
          "options": [
            {
              "flag": "--index",
              "description": "List the topic's sections and their keys, even for a topic with one section",
              "type": "boolean"
            },
            {
              "flag": "--full",
              "description": "Print the whole topic instead of its sections (text; `--json` returns the whole topic unless --index). Cannot be set with --index",
              "type": "boolean"
            },
            {
              "flag": "--depth <levels>",
              "description": "How many levels of the docs tree to read below a namespace: 0 for the namespace alone, 1 for its children (what a read without --depth shows), all for everything below it. On the topic list, where a namespace otherwise lists alone, it names the docs below each one by the route that opens them, one line each. With it on a namespace read, --detail sets how much of each doc below shows: brief (one line each, the default), compact (with its sections), or full; the topic list is one line per doc whatever the detail",
              "type": "string"
            }
          ],
          "json": true,
          "responseTypes": [
            "docs.list",
            "docs.detail",
            "docs.index",
            "docs.detail.section",
            "docs.node"
          ],
          "examples": [
            "astryx docs",
            "astryx docs theme",
            "astryx docs spacing --json",
            "astryx docs theme quick-start",
            "astryx docs cli",
            "astryx docs cli --depth all",
            "astryx docs --depth all",
            "astryx docs authoring --depth all --detail full",
            "astryx docs cli/api/functions/search",
            "astryx docs authoring/quick-start --full"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "success"
            },
            {
              "code": 1,
              "when": "unknown topic or route, a section that matches no section or more than one, or a --depth that is not a number of levels or all"
            }
          ],
          "outsideProject": "same"
        },
        {
          "name": "doctor",
          "description": "Diagnose Astryx projects and integration packages",
          "arguments": [],
          "options": [
            {
              "flag": "--built <path>",
              "description": "Also check a finished build before you deliver it: a project folder, a build output folder, or one built HTML file. Fails when it does not use Astryx at all, and warns with each raw element, icon or custom style in its source.",
              "type": "string"
            }
          ],
          "json": true,
          "responseTypes": [
            "doctor"
          ],
          "examples": [
            "astryx doctor",
            "astryx doctor --json",
            "astryx doctor --built dist",
            "astryx doctor integration validate @acme/widgets",
            "astryx doctor integration templates @acme/widgets",
            "astryx doctor integration components @acme/widgets",
            "astryx doctor integration docs @acme/widgets"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "no checks failed (warnings are allowed)"
            },
            {
              "code": 1,
              "when": "one or more checks failed"
            }
          ],
          "outsideProject": "own",
          "subcommands": [
            {
              "name": "doctor integration",
              "description": "Check an integration package while authoring it",
              "arguments": [],
              "options": [],
              "json": false,
              "examples": [
                "astryx doctor integration validate",
                "astryx doctor integration templates",
                "astryx doctor integration components",
                "astryx doctor integration docs"
              ],
              "exitCodes": [
                {
                  "code": 0,
                  "when": "help is shown or the selected check has no errors"
                },
                {
                  "code": 1,
                  "when": "the selected check reports an error"
                }
              ],
              "subcommands": [
                {
                  "name": "doctor integration components",
                  "description": "Check integration component names, replacements, and documented props",
                  "arguments": [
                    {
                      "name": "package",
                      "required": false,
                      "variadic": false,
                      "description": "Installed integration package name; omit to check the package in the current directory."
                    }
                  ],
                  "options": [],
                  "json": true,
                  "responseTypes": [
                    "integration.component-conflicts"
                  ],
                  "examples": [
                    "astryx doctor integration components",
                    "astryx doctor integration components @acme/widgets --json"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "the check completed; component name conflicts, replaces findings for a package without the CLI range, props that differ from the code, and links that name no doc are warnings"
                    },
                    {
                      "code": 1,
                      "when": "the integration is invalid, Core cannot be resolved, or a package that declares the CLI range has an invalid replaces"
                    }
                  ],
                  "outsideProject": "same"
                },
                {
                  "name": "doctor integration docs",
                  "description": "Check an integration's docs: the docs tree they add, every link, and overlaps with Core topics",
                  "arguments": [
                    {
                      "name": "package",
                      "required": false,
                      "variadic": false,
                      "description": "Installed integration package name; omit to check the package in the current directory."
                    }
                  ],
                  "options": [],
                  "json": true,
                  "responseTypes": [
                    "integration.doc-conflicts"
                  ],
                  "examples": [
                    "astryx doctor integration docs",
                    "astryx doctor integration docs @acme/widgets --json"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "all Core overlaps are explicitly declared or no overlap exists"
                    },
                    {
                      "code": 1,
                      "when": "an overlap is accidental, a doc is invalid, a namespace or placement fails, or a reference block cannot include what it names. A link that names no doc is a warning, and does not change the exit code"
                    }
                  ],
                  "outsideProject": "same"
                },
                {
                  "name": "doctor integration templates",
                  "description": "Validate integration template replacements and Core id overlaps",
                  "arguments": [
                    {
                      "name": "package",
                      "required": false,
                      "variadic": false,
                      "description": "Installed integration package name; omit to check the package in the current directory."
                    }
                  ],
                  "options": [],
                  "json": true,
                  "responseTypes": [
                    "integration.template-conflicts"
                  ],
                  "examples": [
                    "astryx doctor integration templates",
                    "astryx doctor integration templates @acme/widgets --json"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "replacement declarations are valid; undeclared id conflicts are warnings"
                    },
                    {
                      "code": 1,
                      "when": "the integration, a template, or a replacement declaration is invalid"
                    }
                  ],
                  "outsideProject": "same"
                },
                {
                  "name": "doctor integration validate",
                  "description": "Validate an integration manifest and its contributions",
                  "arguments": [
                    {
                      "name": "package",
                      "required": false,
                      "variadic": false,
                      "description": "Installed integration package name; omit to validate the package in the current directory."
                    }
                  ],
                  "options": [],
                  "json": true,
                  "responseTypes": [
                    "integration.validate"
                  ],
                  "examples": [
                    "astryx doctor integration validate",
                    "astryx doctor integration validate @acme/widgets --json"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "no error-severity issues (warnings, including doc type findings, are allowed)"
                    },
                    {
                      "code": 1,
                      "when": "one or more error-severity issues"
                    }
                  ],
                  "outsideProject": "own"
                }
              ]
            }
          ]
        },
        {
          "name": "experimental",
          "description": "[experimental] Try features that may change in a patch release: icon sets (find icons, build an icon-set package)",
          "arguments": [],
          "options": [],
          "json": false,
          "examples": [
            "astryx experimental",
            "astryx experimental icon delete",
            "astryx experimental render page.tsx"
          ],
          "exitCodes": [
            {
              "code": 0,
              "when": "help is shown or a subcommand succeeds"
            },
            {
              "code": 1,
              "when": "an unknown subcommand or a subcommand failure"
            }
          ],
          "subcommands": [
            {
              "name": "experimental icon",
              "description": "[experimental] Find an icon by meaning, or build an icon set from a library (guide: astryx docs cli/experimental/icon-sets)",
              "arguments": [
                {
                  "name": "query",
                  "required": false,
                  "variadic": true,
                  "description": ""
                }
              ],
              "options": [
                {
                  "flag": "--list",
                  "description": "List the installed icon sets and do nothing else; a query is refused",
                  "type": "boolean"
                },
                {
                  "flag": "--set <name>",
                  "description": "Search one set, by name or <package>/<set>",
                  "type": "string"
                },
                {
                  "flag": "--limit <n>",
                  "description": "Max number of matches, a positive integer (default 10)",
                  "type": "string"
                },
                {
                  "flag": "--definitions",
                  "description": "Every Astryx icon definition, one line each: name, built in or not, description, words",
                  "type": "boolean"
                },
                {
                  "flag": "--all-icons",
                  "description": "With --set and no words: every icon of that set, one line each (id, words, definitions)",
                  "type": "boolean"
                }
              ],
              "json": true,
              "responseTypes": [
                "icon.search",
                "icon.detail",
                "icon.definitions",
                "icon.setIcons",
                "icon.list"
              ],
              "examples": [
                "astryx experimental icon delete",
                "astryx experimental icon outline/trash",
                "astryx experimental icon --list --json",
                "astryx experimental icon --set outline --all-icons",
                "astryx experimental icon arrow --set outline --limit 3"
              ],
              "exitCodes": [
                {
                  "code": 0,
                  "when": "success (including zero matches)"
                },
                {
                  "code": 1,
                  "when": "no query and no --list, a query with --list, a --limit that is not a positive integer, or a set or icon that is not installed"
                }
              ],
              "outsideProject": "same",
              "subcommands": [
                {
                  "name": "experimental icon add",
                  "description": "[experimental] Register one icon you chose from a library in your icon set",
                  "arguments": [
                    {
                      "name": "export",
                      "required": false,
                      "variadic": false,
                      "description": ""
                    }
                  ],
                  "options": [
                    {
                      "flag": "--from <module>",
                      "description": "The module the icon is exported from: a package, a subpath, or a ./ path to a file inside this package",
                      "type": "string"
                    },
                    {
                      "flag": "--definition <name>",
                      "description": "Map the icon to this icon definition",
                      "type": "string"
                    },
                    {
                      "flag": "--new-definition <name>",
                      "description": "Add your set's own definition, named in camelCase (aiHelper) or kebab-case (ai-helper), then map the icon to it; needs --description and --words",
                      "type": "string"
                    },
                    {
                      "flag": "--description <text>",
                      "description": "With --new-definition: what the icon is for",
                      "type": "string"
                    },
                    {
                      "flag": "--words <list>",
                      "description": "With --new-definition: comma-separated words people search for",
                      "type": "string"
                    },
                    {
                      "flag": "--default",
                      "description": "The module's default export is the icon; your set's module must re-export it under <export>",
                      "type": "boolean"
                    },
                    {
                      "flag": "--variant <name>",
                      "description": "Add the export as this variant of an existing icon: one of the set's declared variants, such as solid",
                      "type": "string"
                    },
                    {
                      "flag": "--all",
                      "description": "With --variant and --from, and no export: add that variant for every icon whose id the module exports, in one run",
                      "type": "boolean"
                    },
                    {
                      "flag": "--id <id>",
                      "description": "The icon's id, instead of the one its name gives",
                      "type": "string"
                    },
                    {
                      "flag": "--set <name>",
                      "description": "The set to edit, when the package ships several",
                      "type": "string"
                    }
                  ],
                  "json": true,
                  "responseTypes": [
                    "icon.add",
                    "icon.addVariants",
                    "icon.definitionMatches"
                  ],
                  "examples": [
                    "astryx experimental icon add Bin --from @acme/glyph-library",
                    "astryx experimental icon add Bin --from @acme/glyph-library --definition delete",
                    "astryx experimental icon add --variant solid --from @heroicons/react/24/solid --all",
                    "astryx experimental icon add Dice5 --from @acme/glyph-library --new-definition random --description 'Pick something at random.' --words dice,shuffle,chance",
                    "astryx experimental icon add Bin --from @acme/glyph-library/solid --id bin --variant solid"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "the icon is added, already present, or the matching definitions are listed"
                    },
                    {
                      "code": 1,
                      "when": "the export is missing or is data, the definition is unknown, the id is taken, or the variant is not one the set declares"
                    }
                  ],
                  "outsideProject": "refuse"
                },
                {
                  "name": "experimental icon map",
                  "description": "[experimental] Register which icon of your set draws an icon definition",
                  "arguments": [
                    {
                      "name": "definition",
                      "required": false,
                      "variadic": false,
                      "description": ""
                    },
                    {
                      "name": "icon",
                      "required": false,
                      "variadic": false,
                      "description": ""
                    }
                  ],
                  "options": [
                    {
                      "flag": "--set <name>",
                      "description": "The set to edit, when the package ships several",
                      "type": "string"
                    },
                    {
                      "flag": "--remove",
                      "description": "Remove the definition's entry; takes no icon",
                      "type": "boolean"
                    },
                    {
                      "flag": "--pairs <list>",
                      "description": "Many entries in one write: <definition>=<icon> pairs, comma-separated; checked together, all or none; an existing entry is replaced",
                      "type": "string"
                    }
                  ],
                  "json": true,
                  "responseTypes": [
                    "icon.mapMany",
                    "icon.map"
                  ],
                  "examples": [
                    "astryx experimental icon map delete trash",
                    "astryx experimental icon map --pairs close=x-mark,error=x-circle,search=magnifying-glass",
                    "astryx experimental icon map delete --remove"
                  ],
                  "exitCodes": [
                    {
                      "code": 0,
                      "when": "the entry is written, removed, or already as asked"
                    },
                    {
                      "code": 1,
                      "when": "the definition is unknown, the set has no such icon, or no set is found"
                    }
                  ],
                  "outsideProject": "refuse"
                },
                {
                  "name": "experimental icon new-definition",
                  "description": "[experimental] Add your icon set's own icon definition",
                  "arguments": [
                    {
                      "name": "name",
                      "required": true,
                      "variadic": false,
                      "description": "The definition name, in camelCase (rocketLaunch) or kebab-case (rocket-launch)"
                    }
                  ],
                  "options": [
                    {
                      "flag": "--dry-run",
                      "description": "Validate and show planned writes without changing files",
                      "type": "boolean"
                    },
                    {
                      "flag": "--set <name>",
                      "description": "The icon set to add it to, when the package ships several",
                      "type": "string"
                    },
                    {
                      "flag": "--description <text>",
                      "description": "One sentence on what an icon with this definition is for",
                      "type": "string"
                    },
                    {
                      "flag": "--words <list>",
                      "description": "Comma-separated words people search for",
                      "type": "string"
                    },
                    {
                      "flag": "--icon <id>",
                      "description": "Also map it to this icon of the set (its `map` entry)",
                      "type": "string"
                    }
                  ],
